ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_private *private_data = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!private_data)
        return -ENODEV;

    if (count == 0)
        return 0;

    spin_lock(&private_data->lock);

    while (bytes_read < count) {
        if (kthread_should_stop()) {
            ret = -EIO;
            break;
        }

        if (signal_pending(current)) {
            ret = -EINTR;
            break;
        }

        if (private_data->disconnected) {
            ret = -ENODEV;
            break;
        }

        if (private_data->queue_size == 0) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                break;
            } else {
                ret = wait_event_interruptible(private_data->read_wait, private_data->queue_size > 0);
                if (ret < 0)
                    break;
            }
        }

        ret = copy_to_user(buffer + bytes_read, private_data->queue_head, private_data->queue_size);
        if (ret != 0) {
            ret = -EFAULT;
            break;
        }

        bytes_read += private_data->queue_size;
        private_data->queue_head += private_data->queue_size;
        private_data->queue_size = 0;

        wake_up(&private_data->write_wait);
    }

    spin_unlock(&private_data->lock);

    if (bytes_read > 0)
        *offset += bytes_read;

    return (ret < 0) ? ret : bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    void *private_data = file->private_data;
    ssize_t total_read = 0;

    if (!private_data) {
        return -EINVAL;
    }

    while (total_read < count) {
        // Lock necessary mutexes and spinlocks
        mutex_lock(&private_data->mutex);
        spin_lock(&private_data->spinlock);

        // Check for disconnection or empty queue
        if (!private_data->is_connected || list_empty(&private_data->queue)) {
            spin_unlock(&private_data->spinlock);
            mutex_unlock(&private_data->mutex);

            // Handle blocking and non-blocking reads
            if (file->f_flags & O_NONBLOCK) {
                return -EAGAIN;
            }

            // Wait for data to be available
            wait_event_interruptible(private_data->wait_queue, !list_empty(&private_data->queue));
            continue;
        }

        // Get data from queue
        struct queue_element *element = list_first_entry(&private_data->queue, struct queue_element, list);
        size_t bytes_to_read = min(count - total_read, element->length);

        // Copy data to user buffer
        if (copy_to_user(buffer + total_read, element->data, bytes_to_read)) {
            spin_unlock(&private_data->spinlock);
            mutex_unlock(&private_data->mutex);
            return -EFAULT;
        }

        total_read += bytes_to_read;

        // Remove element from queue
        list_del(&element->list);
        kfree(element);

        spin_unlock(&private_data->spinlock);
        mutex_unlock(&private_data->mutex);
    }

    *offset += total_read;
    return total_read;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_dev *dev = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!dev)
        return -EFAULT;

    spin_lock(&dev->lock);

    while (count > 0) {
        if (kthread_should_stop()) {
            spin_unlock(&dev->lock);
            return -ENODEV;
        }

        if (dev->disconnected) {
            spin_unlock(&dev->lock);
            return -EIO;
        }

        if (dev->data_available) {
            ret = copy_to_user(buffer + bytes_read, dev->buffer, dev->data_available);
            if (ret) {
                spin_unlock(&dev->lock);
                return -EFAULT;
            }

            bytes_read += dev->data_available;
            dev->data_available = 0;
            dev->buffer = NULL;
        } else if (file->f_flags & O_NONBLOCK) {
            spin_unlock(&dev->lock);
            return 0;
        } else {
            wait_event_interruptible(dev->wait_queue, dev->data_available || dev->disconnected);
        }
    }

    spin_unlock(&dev->lock);
    return bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_private *priv = file->private_data;
    ssize_t total_bytes_read = 0;
    int ret;

    if (!priv)
        return -EFAULT;

    spin_lock(&priv->queue_lock);

    while (total_bytes_read < (ssize_t)count) {
        struct timer_data *data;

        if (list_empty(&priv->queue)) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                goto exit;
            }

            ret = wait_event_interruptible(priv->read_wait, !list_empty(&priv->queue));
            if (ret < 0)
                goto exit;

            if (priv->disconnected) {
                ret = -EIO;
                goto exit;
            }
        }

        data = list_first_entry(&priv->queue, struct timer_data, list);
        size_t bytes_to_read = min(count - total_bytes_read, (size_t)data->length);

        ret = copy_to_user(buffer + total_bytes_read, data->data, bytes_to_read);
        if (ret != 0) {
            ret = -EFAULT;
            goto exit;
        }

        total_bytes_read += bytes_to_read;
        list_del(&data->list);
        kfree(data);
    }

    ret = total_bytes_read;

exit:
    spin_unlock(&priv->queue_lock);
    return ret;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    void *private_data = file->private_data;
    ssize_t total_read = 0;
    int ret;

    if (!private_data)
        return -EFAULT;

    while (total_read < (ssize_t)count) {
        void *data;
        size_t data_size;

        /* Lock mutexes and spinlocks as required */
        mutex_lock(&private_data->mutex);
        spin_lock(&private_data->spinlock);

        if (kthread_should_stop() || private_data->disconnected) {
            spin_unlock(&private_data->spinlock);
            mutex_unlock(&private_data->mutex);
            return -ENODEV;
        }

        data = get_next_data_from_queue(private_data, &data_size);
        if (!data) {
            if (file->f_flags & O_NONBLOCK) {
                spin_unlock(&private_data->spinlock);
                mutex_unlock(&private_data->mutex);
                return -EAGAIN;
            }

            wait_for_data(private_data);
            continue;
        }

        if (data_size > count - total_read) {
            data_size = count - total_read;
        }

        ret = copy_to_user(buffer + total_read, data, data_size);
        if (ret) {
            spin_unlock(&private_data->spinlock);
            mutex_unlock(&private_data->mutex);
            return -EFAULT;
        }

        total_read += data_size;

        spin_unlock(&private_data->spinlock);
        mutex_unlock(&private_data->mutex);

        if (signal_pending(current))
            break;
    }

    return total_read ? total_read : -EIO;
}
